const listWatcherViews = `-- name: ListWatcherViews :many
SELECT w.id, w.team_id, w.created_by, w.agent_id, w.hub, w.name, w.objective, w.source, w.target_id, w.selector, w.hook_id, w.every_seconds, w.cooldown_seconds, w.state, w.status, w.paused_reason, w.deleted_at, w.next_check_at, w.last_run_at, w.consecutive_failures, w.proposed_run, w.proposed_in, w.created_at, w.updated_at, w.target, w.target_label, ss.id AS session_id, ss.channel_id AS session_channel_id,
       coalesce(t.url, '')::text AS url,
       coalesce(lc.outcome, '')::text AS last_outcome, lc.checked_at AS last_checked_at
FROM watchers w
JOIN sessions ss ON ss.watcher_id = w.id
LEFT JOIN watch_targets t ON t.id = w.target_id
LEFT JOIN watcher_checks lc ON lc.id = (
    SELECT c.id FROM watcher_checks c WHERE c.watcher_id = w.id ORDER BY c.checked_at DESC, c.id DESC LIMIT 1)
WHERE w.team_id = $1
  AND ($2::bool OR w.created_by = $3::uuid)
  AND (CASE WHEN cardinality($4::text[]) = 0 THEN w.status <> 'deleted'
            ELSE w.status = ANY($4::text[]) END)
  AND ($5::timestamptz IS NULL
       OR (w.created_at, w.id) < ($5::timestamptz, $6::uuid))
ORDER BY w.created_at DESC, w.id DESC
LIMIT $7
`

type ListWatcherViewsParams struct {
	TeamID       uuid.UUID
	Everyone     bool
	Viewer       uuid.UUID
	Statuses     []string
	AfterCreated *time.Time
	AfterID      *uuid.UUID
	PageSize     int32
}

type ListWatcherViewsRow struct {
	Watcher          Watcher
	SessionID        uuid.UUID
	SessionChannelID *uuid.UUID
	Url              string
	LastOutcome      string
	LastCheckedAt    *time.Time
}

// A team's watchers, newest first, a page at a time: the viewer's own unless
// everyone's is asked for by one who may see them; deleted ones only when
// asked for by status.
func (q *Queries) ListWatcherViews(ctx context.Context, arg ListWatcherViewsParams) ([]ListWatcherViewsRow, error) {
	rows, err := q.db.Query(ctx, listWatcherViews,
		arg.TeamID,
		arg.Everyone,
		arg.Viewer,
		arg.Statuses,
		arg.AfterCreated,
		arg.AfterID,
		arg.PageSize,
	)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	var items []ListWatcherViewsRow
	for rows.Next() {
		var i ListWatcherViewsRow
		if err := rows.Scan(
			&i.Watcher.ID,
			&i.Watcher.TeamID,
			&i.Watcher.CreatedBy,
			&i.Watcher.AgentID,
			&i.Watcher.Hub,
			&i.Watcher.Name,
			&i.Watcher.Objective,
			&i.Watcher.Source,
			&i.Watcher.TargetID,
			&i.Watcher.Selector,
			&i.Watcher.HookID,
			&i.Watcher.EverySeconds,
			&i.Watcher.CooldownSeconds,
			&i.Watcher.State,
			&i.Watcher.Status,
			&i.Watcher.PausedReason,
			&i.Watcher.DeletedAt,
			&i.Watcher.NextCheckAt,
			&i.Watcher.LastRunAt,
			&i.Watcher.ConsecutiveFailures,
			&i.Watcher.ProposedRun,
			&i.Watcher.ProposedIn,
			&i.Watcher.CreatedAt,
			&i.Watcher.UpdatedAt,
			&i.Watcher.Target,
			&i.Watcher.TargetLabel,
			&i.SessionID,
			&i.SessionChannelID,
			&i.Url,
			&i.LastOutcome,
			&i.LastCheckedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}

