const pruneWatcherChecks = `-- name: PruneWatcherChecks :execrows
DELETE FROM watcher_checks c
USING (
    SELECT id FROM (
        SELECT id, row_number() OVER (PARTITION BY watcher_id ORDER BY checked_at DESC, id DESC) AS n
        FROM watcher_checks
    ) ranked
    WHERE n > $1::int
    LIMIT $2
) old
WHERE c.id = old.id
`

type PruneWatcherChecksParams struct {
	Keep  int32
	Batch int32
}

// Each watcher keeps its newest checks; the rest go a batch at a time.
func (q *Queries) PruneWatcherChecks(ctx context.Context, arg PruneWatcherChecksParams) (int64, error) {
	result, err := q.db.Exec(ctx, pruneWatcherChecks, arg.Keep, arg.Batch)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

